CREATE TABLE BASE_AI_MODEL_ROUTING (F_Id BIGINT PRIMARY KEY, F_Stage INT NOT NULL, F_StageName NVARCHAR(50), F_Provider NVARCHAR(50) NOT NULL, F_Model NVARCHAR(100) NOT NULL, F_Priority INT NOT NULL DEFAULT 1, F_MaxRetries INT NOT NULL DEFAULT 3, F_TimeoutMs INT NOT NULL DEFAULT 60000, F_CircuitBreakerThreshold INT DEFAULT 3, F_CircuitBreakerResetMs INT DEFAULT 300000, F_Enabled BIT NOT NULL DEFAULT 1, F_CreatorTime DATETIME NOT NULL DEFAULT GETDATE(), F_CreatorUserId BIGINT, F_ModifyTime DATETIME, F_ModifyUserId BIGINT, F_DeleteMark BIT NOT NULL DEFAULT 0);
CREATE INDEX IX_ROUTING_STAGE ON BASE_AI_MODEL_ROUTING(F_Stage, F_Priority, F_DeleteMark);
